import{_ as a,o as e,c as n,a3 as i}from"./chunks/framework.Zs2ruvLs.js";const h=JSON.parse('{"title":"Ambient Privacy & Graph Entropy","description":"","frontmatter":{},"headers":[],"relativePath":"protocol/ambient-privacy.md","filePath":"protocol/ambient-privacy.md","lastUpdated":1791334697000}'),s={name:"protocol/ambient-privacy.md"};function r(o,t,l,c,d,m){return e(),n("div",null,[...t[0]||(t[0]=[i('<h1 id="ambient-privacy-graph-entropy" tabindex="-1">Ambient Privacy &amp; Graph Entropy <a class="header-anchor" href="#ambient-privacy-graph-entropy" aria-label="Permalink to &quot;Ambient Privacy &amp; Graph Entropy&quot;">​</a></h1><p><strong>Status</strong>: Architectural Principle &amp; Cryptographic Thesis<br><strong>Primary Specification</strong>: <code>docs/ambient-privacy-and-graph-entropy.md</code></p><hr><h2 id="_1-executive-summary" tabindex="-1">1. Executive Summary <a class="header-anchor" href="#_1-executive-summary" aria-label="Permalink to &quot;1. Executive Summary&quot;">​</a></h2><p>Traditional cryptocurrency privacy models—most notably centralized mixers and opt-in smart contract pools (e.g., Tornado Cash, CoinJoin)—suffer from two structural vulnerabilities:</p><ol><li><strong>Regulatory and Operational Points of Failure</strong>: Shared liquidity pools commingle user funds in a single contract, establishing an identifiable money transmission nexus and creating targets for OFAC sanctions and blacklisting.</li><li><strong>Negative Privacy Externalities</strong>: Using an opt-in mixer is an explicit, conspicuous act. Users who deposit into a mixer are assigned a &quot;taint&quot; score by blockchain surveillance algorithms (Chainalysis, TRM Labs).</li></ol><p>Frank operates on an alternative architectural paradigm: <strong>Ambient Privacy through Indistinguishability</strong>.</p><hr><h2 id="_2-comparison-opt-in-pools-vs-ambient-privacy" tabindex="-1">2. Comparison: Opt-In Pools vs. Ambient Privacy <a class="header-anchor" href="#_2-comparison-opt-in-pools-vs-ambient-privacy" aria-label="Permalink to &quot;2. Comparison: Opt-In Pools vs. Ambient Privacy&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">Dimension</th><th style="text-align:left;">Opt-In Mixer Pools (Tornado Cash / Shielded Pools)</th><th style="text-align:left;">Frank Autonomous Ambient Privacy</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>On-Chain Footprint</strong></td><td style="text-align:left;">Contract interaction with a known mixer address (<code>0xd90e...</code>).</td><td style="text-align:left;">Ordinary EOA-to-EOA native gas transfer (<code>data: &#39;0x&#39;</code>).</td></tr><tr><td style="text-align:left;"><strong>Regulatory Nexus</strong></td><td style="text-align:left;">Commingling contract / pool acts as an unincorporated money transmitter.</td><td style="text-align:left;">100% client-side self-custody; zero shared contracts.</td></tr><tr><td style="text-align:left;"><strong>Blacklisting / Taint</strong></td><td style="text-align:left;"><strong>Trivial to blacklist</strong>: Exchanges flag any address 1–2 hops from the mixer contract.</td><td style="text-align:left;"><strong>Impossible to blacklist</strong>: To block Frank, an exchange would have to block all standard P2P transfers.</td></tr><tr><td style="text-align:left;"><strong>Privacy Externality</strong></td><td style="text-align:left;"><strong>Negative</strong>: Opting into privacy flags the user and taints their recipients.</td><td style="text-align:left;"><strong>Positive</strong>: Shields ordinary network users by creating plausible deniability across all P2P transfers.</td></tr><tr><td style="text-align:left;"><strong>Anonymity Set</strong></td><td style="text-align:left;">Limited strictly to active users of the specific mixer pool.</td><td style="text-align:left;"><strong>The entire transaction volume of the underlying blockchain</strong>.</td></tr></tbody></table><hr><h2 id="_3-how-ambient-entropy-protects-everyone" tabindex="-1">3. How Ambient Entropy Protects Everyone <a class="header-anchor" href="#_3-how-ambient-entropy-protects-everyone" aria-label="Permalink to &quot;3. How Ambient Entropy Protects Everyone&quot;">​</a></h2><p>Blockchain intelligence firms rely on automated heuristic graph clustering to track financial activity:</p><ol><li><strong>Change Address Heuristic</strong>: If an address spends funds to two destinations, and one output is fresh, surveillance algorithms classify the fresh address as internal change.</li><li><strong>Peel Chain Heuristic</strong>: Sequential transaction chains (<span class="katex"><span class="katex-mathml"><math><semantics><mrow><mi>A</mi><mo>→</mo><mi>B</mi><mo>→</mo><mi>C</mi><mo>→</mo><mi>D</mi></mrow><annotation encoding="application/x-tex">A \\to B \\to C \\to D</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.68333em;"></span><span class="strut bottom" style="height:0.68333em;vertical-align:0em;"></span><span class="base textstyle uncramped"><span class="mord mathit">A</span><span class="mrel">→</span><span class="mord mathit" style="margin-right:0.05017em;">B</span><span class="mrel">→</span><span class="mord mathit" style="margin-right:0.07153em;">C</span><span class="mrel">→</span><span class="mord mathit" style="margin-right:0.02778em;">D</span></span></span></span>) are assumed to belong to a single entity peeling off payments.</li></ol><h3 id="mathematical-indistinguishability" tabindex="-1">Mathematical Indistinguishability <a class="header-anchor" href="#mathematical-indistinguishability" aria-label="Permalink to &quot;Mathematical Indistinguishability&quot;">​</a></h3><p>When Frank wallets execute single-use stealth address transfers:</p> \\text{Address}_A \\xrightarrow{0.084 \\text{ MON}} \\text{Address}_B <p>To an external blockchain crawler, this transaction possesses standard gas limits, ordinary value, and no smart contract data markers. It is mathematically indistinguishable from:</p><ul><li>A user paying a friend for dinner.</li><li>An over-the-counter (OTC) trade settlement.</li><li>A merchant receiving payment.</li><li>An autonomous Frank wallet sweeping residual change dust to a new address.</li></ul><p>Because Frank transactions blend indistinguishably into everyday network traffic, they inject mathematical entropy and plausible deniability into the entire chain, protecting both Frank users and uninvolved third parties.</p>',20)])])}const g=a(s,[["render",r]]);export{h as __pageData,g as default};
